// ---------------------------------------------------------------- helpers

// first difference of two call lists, short message (never print two big lists)
function sameCalls(actual, expected, label) {
  const n = Math.max(actual.length, expected.length);
  for (let i = 0; i < n; i++) {
    const a = JSON.stringify(actual[i]), e = JSON.stringify(expected[i]);
    if (a !== e) assert.fail(label + ': call ' + i + ' of ' + actual.length + ' (expected ' + expected.length + '): got ' + a + ', expected ' + e);
  }
  // also compare numbers with Object.is (JSON hides -0)
  for (let i = 0; i < n; i++) {
    for (let k = 0; k < expected[i].length; k++) {
      if (typeof expected[i][k] === 'number' && !Object.is(actual[i][k], expected[i][k])) assert.fail(label + ': call ' + i + ' arg ' + k);
    }
  }
}

// the colour tables of colours 0..9 (game.js:3325-3327, DWH 2.4) and the entry slSprites makes (DS 2.11 step 1)
const RRS = [192, 144, 128, 128, 238, 255, 255, 255, 224, 255];
const GGS = [128, 153, 208, 255, 238, 160, 144, 64, 48, 255];
const BBS = [255, 255, 208, 128, 112, 96, 144, 64, 224, 255];
const CS = ['#c080ff', '#9099ff', '#80d0d0', '#80ff80', '#eeee70', '#ffa060', '#ff9090', '#ff4040', '#e030e0', '#ffffff'];
function newEntry(i) {
  return { imgs: [], fws: [], fhs: [], fw2s: [], fh2s: [], gimgs: [], gfws: [], gfhs: [], gfw2s: [], gfh2s: [],
    oimgs: [], ofws: [], ofhs: [], ofw2s: [], ofh2s: [], cs: CS[i] };
}
const PCI = [];
const SPRITE_LOGS = [];
for (let i = 0; i <= 9; i++) {
  LOG = [];
  const o = newEntry(i);
  W.buildFoodSprites(o, i, RRS[i], GGS[i], BBS[i]);
  SPRITE_LOGS.push(LOG.map((e) => e.slice(1)));
  PCI.push(o);
}
LOG = [];
PCI.forEach((p, i) => {
  p.imgs.forEach((cv, k) => { cv.__tag = 'core' + i + '_' + k; });
  p.gimgs.forEach((cv, k) => { cv.__tag = 'glow' + i + '_' + k; });
  p.oimgs.forEach((cv, k) => { cv.__tag = 'shadow' + i + '_' + k; });
  p.pr_imgs.forEach((cv, k) => { cv.__tag = 'prey' + i + '_' + k; });
});

function food(f) {      // a food with its sprite picks resolved (what newFood stores, DWH 2.5)
  const p = PCI[f.cv];
  return Object.assign({}, f, {
    fi: p.imgs[f.cv2], fw: p.fws[f.cv2], fh: p.fhs[f.cv2], fw2: p.fw2s[f.cv2], fh2: p.fh2s[f.cv2],
    ofi: p.oimgs[f.cv2], ofw: p.ofws[f.cv2], ofh: p.ofhs[f.cv2], ofw2: p.ofw2s[f.cv2], ofh2: p.ofh2s[f.cv2],
    gfi: p.gimgs[f.gcv], gfw: p.gfws[f.gcv], gfh: p.gfhs[f.gcv], gfw2: p.gfw2s[f.gcv], gfh2: p.gfh2s[f.gcv],
    g2fi: p.gimgs[f.g2cv], g2fw: p.gfws[f.g2cv], g2fh: p.gfhs[f.g2cv], g2fw2: p.gfw2s[f.g2cv], g2fh2: p.gfh2s[f.g2cv],
  });
}
function prey(r) {      // a prey with its sprite picks (largest glow, DWH 2.5)
  const p = PCI[r.cv];
  return Object.assign({ fi: p.pr_imgs[r.cv2], fw: p.pr_fws[r.cv2], fh: p.pr_fhs[r.cv2], fw2: p.pr_fw2s[r.cv2],
    fh2: p.pr_fh2s[r.cv2], gfi: p.gimgs[16], gfw: p.gfws[16], gfh: p.gfhs[16], gfw2: p.gfw2s[16], gfh2: p.gfh2s[16] }, r);
}

// the camera boxes, as slLoop's prologue writes them (game.js:5195-5209, DWH 2.2 row 5)
function boxes(S) {
  S.view_ang = Math.atan2(S.view_yy - S.grd, S.view_xx - S.grd);
  S.view_dist = Math.sqrt((S.view_xx - S.grd) * (S.view_xx - S.grd) + (S.view_yy - S.grd) * (S.view_yy - S.grd));
  S.bpx1 = S.view_xx - (S.mww2 / S.gsc + 84); S.bpy1 = S.view_yy - (S.mhh2 / S.gsc + 84);
  S.bpx2 = S.view_xx + (S.mww2 / S.gsc + 84); S.bpy2 = S.view_yy + (S.mhh2 / S.gsc + 84);
  S.fpx1 = S.view_xx - (S.mww2 / S.gsc + 24); S.fpy1 = S.view_yy - (S.mhh2 / S.gsc + 24);
  S.fpx2 = S.view_xx + (S.mww2 / S.gsc + 24); S.fpy2 = S.view_yy + (S.mhh2 / S.gsc + 24);
  S.apx1 = S.view_xx - (S.mww2 / S.gsc + 210); S.apy1 = S.view_yy - (S.mhh2 / S.gsc + 210);
  S.apx2 = S.view_xx + (S.mww2 / S.gsc + 210); S.apy2 = S.view_yy + (S.mhh2 / S.gsc + 210);
}

// collaborators on the namespace (BUILD-BRIEF 10.1): stubs that leave a marker in the mc call stream
let LV = null;          // what the prologue hands back: null (not animating) or {lvx, lvy}
let PROLOGUE_CALLS = 0;
D.rand = () => 0.5;
D.slLoop = { redrawPrologue(S) { PROLOGUE_CALLS++; LOG.push(['mc', '#prologue']); return LV; } };
D.slDrawSnake = {
  drawNames(S, ctx) { LOG.push(['mc', '#drawNames', ctx === S.mc.getContext('2d')]); },
  updateVisibility() { LOG.push(['mc', '#updateVisibility']); },
  drawSnakes(S, ctx, rand) { LOG.push(['mc', '#drawSnakes', ctx === S.mc.getContext('2d'), rand === D.rand]); },
};
D.slHud = { updateLengthBox() { LOG.push(['mc', '#updateLengthBox']); } };

// one test scene: their drawCtx inputs (DWH 9 common context), our init first so S is bound
function scene(over, opts) {
  const S = {};
  W.init(S, '/');
  Object.assign(S, {
    mc: makeCanvas('mc', 1500, 845),
    mww: 1500, mhh: 845, mww2: 750, mhh2: 422.5, mwwp50: 1550, mhhp50: 895, mwwp150: 1650, mhhp150: 995,
    gsc: SGSC, view_xx: 20000, view_yy: 21000, grd: 16384, bgw2: 599, bgh2: 519, bgx2: 0, bgy2: 0,
    ggbg: true, gbgmc: makeCanvas('gbgmc', 1500, 845), bgp2: PATTERN, high_quality: true, gla: 1,
    foods: [], foods_c: 0, preys: [], slithers: [], slither: null,
  }, over || {});
  if (S.flux_grd === undefined) S.flux_grd = S.grd * .98;
  S.foods_c = S.foods.length;
  boxes(S);
  const o = opts || {};
  LV = { lvx: o.lvx !== undefined ? o.lvx : S.view_xx, lvy: o.lvy !== undefined ? o.lvy : S.view_yy };
  return S;
}
function frame(S) {
  LOG = [];
  W.redraw();
  const all = callsOf('mc');
  LOG = [];
  return all;
}

