test('9.1 food and prey sprite sizes, every colour 0..9', () => {
  for (let i = 0; i <= 9; i++) {
    const o = PCI[i];
    assert.strictEqual(o.ic, V.spriteTable.count);
    assert.deepStrictEqual(o.fws, V.spriteTable.core);
    assert.deepStrictEqual(o.gfws, V.spriteTable.glow);
    assert.deepStrictEqual(o.ofws, V.spriteTable.shadow);
    assert.strictEqual(o.pr_imgs.length, V.spriteTable.preyCount);
    assert.deepStrictEqual(o.pr_fws, V.spriteTable.prey);
    const lists = [['imgs', 'fws', 'fhs', 'fw2s', 'fh2s'], ['gimgs', 'gfws', 'gfhs', 'gfw2s', 'gfh2s'],
      ['oimgs', 'ofws', 'ofhs', 'ofw2s', 'ofh2s'], ['pr_imgs', 'pr_fws', 'pr_fhs', 'pr_fw2s', 'pr_fh2s']];
    for (const [img, w, h, w2, h2] of lists) {
      o[img].forEach((cv, k) => {
        assert.strictEqual(cv.width, o[w][k]); assert.strictEqual(cv.height, o[h][k]);
        assert.strictEqual(o[h][k], o[w][k]); assert.strictEqual(o[w2][k], o[w][k] / 2); assert.strictEqual(o[h2][k], o[h][k] / 2);
      });
    }
  }
});

