// ---------------------------------------------------------------- 9.7 border

function borderCheck(S, ref, label) {
  const calls = plain(frame(S));
  const before = cat(L4_HQ, TILE00, E.A, E.B, E.P, E.R13, E.C, E.PG);
  sameCalls(calls.slice(0, before.length), before, label + ' before');
  const border = calls.slice(before.length, calls.length - 1);
  sameCalls(calls.slice(calls.length - 1), E.END, label + ' end');
  const counts = {};
  border.forEach((c) => { counts[c[0]] = (counts[c[0]] || 0) + 1; });
  assert.deepStrictEqual(counts, ref.counts);
  sameCalls(border.slice(0, ref.head.length), ref.head, label + ' head');
  const b2 = border.map((c) => c[0]).lastIndexOf('beginPath');
  sameCalls(border.slice(b2 - ref.pass1Last3.length, b2), ref.pass1Last3, label + ' pass 1 end');
  sameCalls(border.slice(b2, b2 + ref.pass2Head.length), ref.pass2Head, label + ' pass 2 head');
  sameCalls(border.slice(border.length - ref.tail.length), ref.tail, label + ' tail');
  assert.strictEqual(S.view_ang, ref.after.view_ang);
  assert.strictEqual(S.view_dist, ref.after.view_dist);
}

