function emptyScene(hq) {
  const S = {};
  W.init(S, '/');
  Object.assign(S, { mc: makeCanvas('mc', 1500, 845), slither: null, slithers: [], foods: [], foods_c: 0, preys: [], gsc: SGSC,
    view_xx: 0, view_yy: 0, view_ang: 0, view_dist: 0, grd: 16384, flux_grd: undefined, mww: 1500, mhh: 845, mww2: 750,
    mhh2: 422.5, mwwp50: 1550, mhhp50: 895, mwwp150: 1650, mhhp150: 995, bgx2: 0, bgy2: 0, bgw2: 599, bgh2: 519, bgp2: null,
    ggbg: true, gbgmc: makeCanvas('gbgmc'), high_quality: hq, gla: hq ? 1 : 0 });
  LV = { lvx: 0, lvy: 0 };
  return S;
}

test('9.18 empty frame, HQ: exactly the 23 calls of golden A frames 164-167, slots in order', () => {
  PROLOGUE_CALLS = 0;
  const S = emptyScene(true);
  const calls = frame(S);
  sameCalls(plain(calls), V.emptyHQ, 'empty HQ');
  assert.strictEqual(V.emptyHQ.length, 23);
  assert.strictEqual(PROLOGUE_CALLS, 1);
  // marker order: prologue first; names, visibility, snakes right after row 13; the length box right before the last restore
  const ops = calls.map((c) => c[0]);
  assert.strictEqual(ops[0], '#prologue');
  const r13 = ops.indexOf('=strokeStyle');
  assert.deepStrictEqual(ops.slice(r13 + 1, r13 + 4), ['#drawNames', '#updateVisibility', '#drawSnakes']);
  assert.deepStrictEqual(calls[r13 + 1], ['#drawNames', true]);
  assert.deepStrictEqual(calls[r13 + 3], ['#drawSnakes', true, true]);
  assert.deepStrictEqual(ops.slice(-2), ['#updateLengthBox', 'restore']);
  assert.strictEqual(ops.filter((o) => o[0] === '#').length, 5);
});

