// ---------------------------------------------------------------- init, images, pattern, glow rebuild (DWH 2.3, BUILD-BRIEF 10.5, 10.7)

test('init sets exactly its 8 keys of S, builds the black 600 x 550 glow image, and points the tile at assetBase', () => {
  const written = [];
  const S = new Proxy({}, { set(t, k, v) { written.push(k); t[k] = v; return true; } });
  const imgs0 = created.img.length;
  LOG = [];
  W.init(S, '/ours/');
  assert.deepStrictEqual(written, ['bgi2', 'bgp2', 'bgee', 'bgees', 'bg_hex', 'ggbg', 'gbgmc', 'gbgi']);
  assert.ok(S.bgi2.__isCanvas);
  assert.strictEqual(S.bgp2, null); assert.strictEqual(S.bgee, null); assert.deepStrictEqual(S.bgees, []);
  assert.strictEqual(S.bg_hex, null); assert.strictEqual(S.ggbg, false); assert.strictEqual(S.gbgmc, null);
  const [tile, glow] = created.img.slice(imgs0);
  assert.strictEqual(created.img.length - imgs0, 2);
  assert.strictEqual(tile.src, '/ours/hexbg.jpg');
  assert.strictEqual(glow, S.gbgi);
  const glowLog = LOG.filter((e) => e[0] !== S.bgi2.__name()).map((e) => e.slice(1));
  sameCalls(glowLog, [['.width', 600], ['.height', 550], ['=fillStyle', '#000000'], ['fillRect', 0, 0, 600, 550], ['toDataURL']], 'glow image');
  assert.ok(/^data:image\/png;base64,FAKE\d+$/.test(glow.src));
  LOG = [];
  const S2 = {};
  W.init(S2);
  assert.strictEqual(created.img[created.img.length - 2].src, '/hexbg.jpg');
});

test('tile onload sizes bgi2 and keeps the image; buildTilePattern makes the pattern', () => {
  const S = {};
  const imgs0 = created.img.length;
  W.init(S, '/');
  Object.assign(S, { bgw2: 599, bgh2: 519 });
  const tile = created.img[imgs0];
  // not loaded yet: the drawImage is still issued, throws, and bgp2 keeps its value
  LOG = [];
  W.buildTilePattern();
  const n = S.bgi2.__name();
  sameCalls(callsOf(n), [['.width', 599], ['.height', 519], ['drawImage', null, 0, 0]], 'pattern, no tile');
  assert.strictEqual(S.bgp2, null);
  const OLD = { __isPattern: true, old: true };
  S.bgp2 = OLD;
  W.buildTilePattern();
  assert.strictEqual(S.bgp2, OLD);
  // the tile loads (as the browser fires it)
  tile.naturalWidth = 599; tile.naturalHeight = 519;
  LOG = [];
  tile.onload.call(tile);
  sameCalls(callsOf(n), [['.width', 599], ['.height', 519]], 'tile onload');
  assert.strictEqual(S.bg_hex, tile);
  LOG = [];
  W.buildTilePattern();
  sameCalls(callsOf(n), [['.width', 599], ['.height', 519], ['drawImage', '<img hexbg.jpg 599x519>', 0, 0],
    ['createPattern', '<' + n + ' 599x519>', 'repeat']], 'pattern');
  assert.ok(S.bgp2 && S.bgp2.__isPattern && S.bgp2 !== OLD);
});

test('glow onload sets ggbg and rebuilds; rebuildGbg reuses its canvas and does nothing before the image', () => {
  const S = {};
  W.init(S, '/');
  Object.assign(S, { mww: 1500, mhh: 845 });
  LOG = [];
  const c0 = created.canvas.length;
  W.rebuildGbg();
  assert.deepStrictEqual(LOG, []);
  assert.strictEqual(S.gbgmc, null);
  S.gbgi.naturalWidth = 600; S.gbgi.naturalHeight = 550;
  S.gbgi.onload.call(S.gbgi);
  assert.strictEqual(S.ggbg, true);
  assert.strictEqual(created.canvas.length, c0 + 1);
  const g = S.gbgmc;
  const img = '<img ' + S.gbgi.src.split('/').pop() + ' 600x550>';
  sameCalls(callsOf(g.__name()), [['.width', 1500], ['.height', 845], ['drawImage', img, 0, 0, 512, 512, 0, 0, 1500, 845]], 'gbg');
  LOG = [];
  S.mww = 1440; S.mhh = 1080;
  W.rebuildGbg();
  assert.strictEqual(S.gbgmc, g);
  assert.strictEqual(created.canvas.length, c0 + 1);
  sameCalls(callsOf(g.__name()), [['.width', 1440], ['.height', 1080], ['drawImage', img, 0, 0, 512, 512, 0, 0, 1440, 1080]], 'gbg 2');
});

